/**
 * @fileoverview
 * 'settings-iris-hardening-page': Iris's own privacy and hardening switches,
 * grouped by topic, on one sub-page of Privacy and security
 * (patches/apply-iris-hardening-page.sh). The template is generated by that
 * script from the toggles the other Iris patches add. The "Security" group
 * (secure connections, secure DNS, strict post-quantum encryption, security
 * keys, certificates) is moved here from the Security page by
 * patches/apply-iris-hardening-security.sh.
 */

import '/shared/settings/prefs/prefs.js';
import 'chrome://resources/cr_elements/cr_link_row/cr_link_row.js';
import '../controls/settings_toggle_button.js';
import '../settings_page/settings_subpage.js';
import '../settings_shared.css.js';
import './security/secure_dns.js';

import {PrefsMixin} from '/shared/settings/prefs/prefs_mixin.js';
import {I18nMixin} from 'chrome://resources/cr_elements/i18n_mixin.js';
import {OpenWindowProxyImpl} from 'chrome://resources/js/open_window_proxy.js';
import {PolymerElement} from 'chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js';

import {loadTimeData} from '../i18n_setup.js';
import {routes} from '../route.js';
import {Router} from '../router.js';
import {SettingsViewMixin} from '../settings_page/settings_view_mixin.js';

import {getTemplate} from './iris_hardening_page.html.js';
import {HttpsFirstModeSetting} from './security/security_page.js';

const SettingsIrisHardeningPageElementBase =
    SettingsViewMixin(I18nMixin(PrefsMixin(PolymerElement)));

export class SettingsIrisHardeningPageElement extends
    SettingsIrisHardeningPageElementBase {
  static get is() {
    return 'settings-iris-hardening-page';
  }

  static get template() {
    return getTemplate();
  }

  static get properties() {
    return {
      showSecureDnsSetting_: {
        type: Boolean,
        readOnly: true,
        value: () => loadTimeData.getBoolean('showSecureDnsSetting'),
      },

      enableSecurityKeysSubpage_: {
        type: Boolean,
        readOnly: true,
        value: () => loadTimeData.getBoolean('enableSecurityKeysSubpage'),
      },

      // "Always use secure connections": on = warn before every http:// page
      // (strict), off = disabled. A Balanced value set elsewhere shows as on.
      httpsFirstModeChecked_: {
        type: Number,
        value: HttpsFirstModeSetting.ENABLED_FULL,
      },

      httpsFirstModeUncheckedValues_: {
        type: Array,
        value: () => [HttpsFirstModeSetting.DISABLED],
      },
    };
  }

  declare private showSecureDnsSetting_: boolean;
  declare private enableSecurityKeysSubpage_: boolean;
  declare private httpsFirstModeChecked_: HttpsFirstModeSetting;
  declare private httpsFirstModeUncheckedValues_: HttpsFirstModeSetting[];

  private onSecurityKeysClick_() {
    Router.getInstance().navigateTo(routes.SECURITY_KEYS);
  }

  private onManageCertificatesClick_() {
    OpenWindowProxyImpl.getInstance().openUrl(
        loadTimeData.getString('certManagementV2URL'));
  }

  // SettingsViewMixin implementation.
  override focusBackButton() {
    this.shadowRoot!.querySelector('settings-subpage')!.focusBackButton();
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'settings-iris-hardening-page': SettingsIrisHardeningPageElement;
  }
}

customElements.define(
    SettingsIrisHardeningPageElement.is, SettingsIrisHardeningPageElement);
